import{_ as o,o as e,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Tooltip","description":"","frontmatter":{},"headers":[],"relativePath":"components/tooltip.md","filePath":"components/tooltip.md"}'),d={name:"components/tooltip.md"};function n(i,t,s,h,c,l){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="tooltip" tabindex="-1">Tooltip <a class="header-anchor" href="#tooltip" aria-label="Permalink to &quot;Tooltip&quot;">​</a></h1><p>Tooltip is a short word that explains the control it wraps.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it to name a control in one word or a few, with a key hint. Every icon button needs one; <a href="./button">Button</a> adds it on its own from the button&#39;s <code>aria-label</code>, with <code>shortcut</code> as the key hint. Wrap other controls in a Tooltip when a word helps. A sentence belongs in the page, a few settings in a <a href="./popover">Popover</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code></td><td></td><td>The word; without it nothing shows</td></tr><tr><td><code>shortcut</code></td><td></td><td>A key hint, written for the platform (⌘Z)</td></tr><tr><td><code>role</code></td><td><code>block</code></td><td><code>box</code> for a control, <code>icon-button</code> for an icon button</td></tr><tr><td><code>keep</code></td><td><code>false</code></td><td>Stays in view where actions show on hover (<code>data-keep</code>)</td></tr><tr><td><code>children</code></td><td>required</td><td>The control</td></tr><tr><td><code>inline</code></td><td><code>false</code></td><td>Always shown beside the control, for documentation</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The tooltip is the inverse of the page (the text color as its surface), in the caption role, as high as a small button with pad-sm at the sides; the key hint has a box of its own, as high as a badge. It is <code>aria-hidden</code>: the control&#39;s own name is what assistive technology reads. It shows on hover after 400ms, so a pointer that only passes by does not show it, and at once on keyboard focus; it hides at once on leaving, on a press, on a scroll and on a resize. It goes above the control, gap-sm away, or below (gap-lg, clear of the pointer), right or left, whichever fits the window first, and never covers the control. It is moved to the body, or into the open modal dialog it is in, so no container clips it. When kata is embedded in a page it does not own, it is moved into the nearest root marked <code>data-kata-root</code> instead of the body (<a href="./../layout#embedding-kata-in-a-page-you-do-not-own">Embedding kata</a>).</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/tooltip/" title="Tooltip" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/tooltip/" target="_blank" rel="noopener">Tooltip</a></figcaption></figure>',10)])])}const m=o(d,[["render",n]]);export{f as __pageData,m as default};
